import java.util.*;
class CircuitBreaker {private final int threshold;private int failures;private boolean open;CircuitBreaker(int threshold){this.threshold=threshold;}String call(boolean success){if(open)return "rejected";if(success){failures=0;return "success";}failures++;if(failures>=threshold)open=true;return "failure";}}
public class Main {public static void main(String[] args){Scanner s=new Scanner(System.in);CircuitBreaker cb=new CircuitBreaker(s.nextInt());int n=s.nextInt();for(int i=0;i<n;i++)System.out.println(cb.call(s.next().equals("ok")));}}
